export function zoomBox(box,factor,anchor,minWidth,maxWidth){const w=Math.max(minWidth,Math.min(maxWidth,box.w*factor)),ratio=w/box.w;return {x:anchor.x-(anchor.x-box.x)*ratio,y:anchor.y-(anchor.y-box.y)*ratio,w,h:box.h*ratio};}
