export function nearestPerson(svg,e,attribute){const direct=e.target.closest('['+attribute+']');if(direct)return direct.getAttribute(attribute);let id=null,best=Infinity;for(const n of svg.querySelectorAll('['+attribute+']')){const r=n.getBoundingClientRect(),d=Math.hypot(Math.max(r.left-e.clientX,0,e.clientX-r.right),Math.max(r.top-e.clientY,0,e.clientY-r.bottom));if(d<=(e.pointerType==='touch'?24:12)&&d<best){best=d;id=n.getAttribute(attribute);}}return id;}
